import {Heading, NavList} from '@primer/react'
import type {EnvironmentListProps} from '../types/deployments'
import {use, useMemo, useState} from 'react'
import {EnvironmentContext} from '../App'

import type {FragmentRef} from 'react-relay'

import {graphql, usePaginationFragment, useFragment} from 'react-relay'
import type {EnvironmentListingsPinned$key} from './__generated__/EnvironmentListingsPinned.graphql'
import type {EnvironmentListListings$key} from './__generated__/EnvironmentListListings.graphql'
import type {EnvironmentListRefetch} from './__generated__/EnvironmentListRefetch.graphql'
import {EnvironmentListItem} from './EnvironmentListItem'
import {GearIcon} from '@primer/octicons-react'

import styles from './EnvironmentListItem.module.css'
import headerStyles from './EnvironmentList.module.css'

interface EnvironmentSideProps extends EnvironmentListProps {
  repositoryRef: FragmentRef<EnvironmentListListings$key>
  adminable: boolean | undefined
  pinnedEnvConnectionId: string
}

type EnvironmentQueryProps = {
  key: EnvironmentListListings$key
}

type EnvironmentPinnedQueryProps = {
  key: EnvironmentListingsPinned$key
}

const useRepositoryEnvironments = ({key}: EnvironmentQueryProps) => {
  const {data, loadNext, hasNext, isLoadingNext} = usePaginationFragment<
    EnvironmentListRefetch,
    EnvironmentListListings$key
  >(
    // eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
    graphql`
      fragment EnvironmentListListings on Repository
      @argumentDefinitions(
        cursor: {type: "String"}
        first: {type: "Int", defaultValue: 50}
        pinnedEnvironmentFilter: {type: "EnvironmentPinnedFilterField", defaultValue: NONE}
      )
      @refetchable(queryName: "EnvironmentListRefetch") {
        environments(first: $first, after: $cursor, pinnedEnvironmentFilter: $pinnedEnvironmentFilter)
          @connection(key: "Repository_environments") {
          edges {
            node {
              id
              name
              isPinned
            }
          }
        }
      }
    `,
    key,
  )
  return {data, loadNext, hasNext, isLoadingNext}
}

const usePinnedEnvironments = ({key}: EnvironmentPinnedQueryProps) => {
  return useFragment(
    // eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
    graphql`
      fragment EnvironmentListingsPinned on Repository
      @argumentDefinitions(
        cursor: {type: "String"}
        first: {type: "Int", defaultValue: 10}
        pinnedEnvironmentFilter: {type: "EnvironmentPinnedFilterField", defaultValue: ONLY}
      ) {
        listPinnedEnvironments: environments(
          first: $first
          after: $cursor
          pinnedEnvironmentFilter: $pinnedEnvironmentFilter
        ) @connection(key: "Repository_listPinnedEnvironments") {
          edges {
            node {
              id
              name
              isPinned
            }
          }
        }
      }
    `,
    key,
  )
}

function isEnvNotInList({
  selectedEnv,
  environmentsList,
}: {
  selectedEnv: string | null | undefined
  environmentsList: ReadonlyArray<{name: string | undefined}>
}) {
  return !!selectedEnv && !environmentsList?.some(env => env.name === selectedEnv)
}

// Latch `envNotInList` to the value computed at the moment `selectedEnv`
// changes. We intentionally do NOT recompute when pagination loads more
// `environmentsList` pages — once we've decided to render the synthetic item
// for an unrecognized `selectedEnv`, we keep rendering it for stability.
//
// Implemented with set-state-during-render (React 19 idiomatic, Compiler-safe)
// rather than a `useMemo` that lies about its dependencies. The early return
// of `nextEnvNotInList` (rather than the canonical React-docs pattern of
// falling through to the stale `envNotInList`) avoids a stale-frame in cases
// where React does not discard the current render output.
function useEnvNotInList({
  selectedEnv,
  environmentsList,
}: {
  selectedEnv: string | null | undefined
  environmentsList: ReadonlyArray<{name: string | undefined}>
}) {
  const [envNotInList, setEnvNotInList] = useState(() => isEnvNotInList({selectedEnv, environmentsList}))
  const [prevSelectedEnv, setPrevSelectedEnv] = useState(selectedEnv)
  if (selectedEnv !== prevSelectedEnv) {
    setPrevSelectedEnv(selectedEnv)
    const nextEnvNotInList = isEnvNotInList({selectedEnv, environmentsList})
    setEnvNotInList(nextEnvNotInList)
    return nextEnvNotInList
  }
  return envNotInList
}

export function EnvironmentList({adminable, repositoryRef, repoScope, pinnedEnvConnectionId}: EnvironmentSideProps) {
  const {data: envData, loadNext: loadNextEnvs, hasNext: hasNextEnvs} = useRepositoryEnvironments({key: repositoryRef})
  const pinnedEnvData = usePinnedEnvironments({key: repositoryRef})
  const selectedEnv = use(EnvironmentContext)
  const environmentsList = useMemo(() => {
    const unpinnedEnvs =
      envData.environments?.edges?.map(environment => {
        return {
          name: environment?.node?.name,
          id: environment?.node?.id,
          pinned: environment?.node?.isPinned,
        }
      }) || []
    const pinnedEnvs =
      pinnedEnvData.listPinnedEnvironments?.edges?.map(environment => {
        return {
          name: environment?.node?.name,
          id: environment?.node?.id,
          pinned: environment?.node?.isPinned,
        }
      }) || []
    return [...pinnedEnvs, ...unpinnedEnvs]
  }, [envData, pinnedEnvData])
  const envNotInList = useEnvNotInList({selectedEnv, environmentsList})

  return (
    <div>
      <div className={headerStyles.headerContainer}>
        <Heading as="h1" className={headerStyles.heading}>
          Deployments
        </Heading>
      </div>
      <NavList data-testid="environment-list" className={styles.environmentlist}>
        <EnvironmentListItem id={'0'} pinned={false} name={'All deployments'} repoScope={repoScope} />
        <NavList.Group title="Environments">
          {envNotInList && (
            <EnvironmentListItem
              id={'-1'}
              name={selectedEnv ? selectedEnv : ''}
              pinned={false}
              repoScope={repoScope}
              pinnedEnvConnectionId={pinnedEnvConnectionId}
            />
          )}
          {environmentsList &&
            environmentsList.map(
              (environment, index) =>
                environment.pinned && (
                  <EnvironmentListItem
                    id={environment.id!}
                    // eslint-disable-next-line @eslint-react/no-array-index-key
                    key={index}
                    pinned={environment.pinned}
                    name={environment.name!}
                    repoScope={repoScope}
                    data-testid="pinned-environment"
                    pinnedEnvConnectionId={pinnedEnvConnectionId}
                  />
                ),
            )}

          {environmentsList &&
            environmentsList.map((environment, index) =>
              (envNotInList && environment.name === selectedEnv) || environment.pinned! ? null : (
                <EnvironmentListItem
                  id={environment.id!}
                  // eslint-disable-next-line @eslint-react/no-array-index-key
                  key={index}
                  pinned={environment.pinned!}
                  name={environment.name!}
                  repoScope={repoScope}
                  pinnedEnvConnectionId={pinnedEnvConnectionId}
                />
              ),
            )}
          {hasNextEnvs && (
            <NavList.Item className="color-fg-accent" onClick={() => loadNextEnvs(50)}>
              Show more environments
            </NavList.Item>
          )}
          {adminable && (
            <>
              <NavList.Divider />
              <NavList.Item href={`/${repoScope}/settings/environments`}>
                <NavList.LeadingVisual>
                  <GearIcon />
                </NavList.LeadingVisual>
                Manage environments
              </NavList.Item>
            </>
          )}
        </NavList.Group>
      </NavList>
    </div>
  )
}
