/**
 * Wraps text segments in HTML with a commit link, preserving existing autolink `<a>` tags.
 *
 * This is compatible with both SSR and browser environments.
 * When commit messages contain autolink references (e.g., Jira issue IDs),
 * the message HTML already has `<a>` tags for those references. Naively wrapping
 * the entire HTML in another `<a>` creates nested anchors, which browsers break.
 *
 * Instead, this function wraps only the text segments that are NOT already inside
 * an `<a>` tag with the commit link. Whitespace-only segments are left unwrapped
 * to avoid creating focusable links with no accessible name.
 */
export function wrapTextWithCommitLink(messageHtml: string, commitUrl: string): string {
  if (!messageHtml) return messageHtml

  const escapedUrl = commitUrl.replace(/[&"<>]/g, c =>
    c === '&' ? '&amp;' : c === '"' ? '&quot;' : c === '<' ? '&lt;' : '&gt;',
  )

  // Split on <a ...>...</a> tags, keeping the delimiters in the result
  const parts = messageHtml.split(/(<a\b[^>]*>[\s\S]*?<\/a>)/gi)

  return parts
    .map(part => {
      // Preserve existing <a> tags (autolinks)
      if (/^<a\b/i.test(part)) {
        return part
      }
      // Wrap non-empty, non-whitespace-only text segments in a commit link
      if (part.trim()) {
        // eslint-disable-next-line github/unescaped-html-literal -- part is server-sanitized HTML, URL is attribute-escaped
        return `<a href="${escapedUrl}">${part}</a>`
      }
      return part
    })
    .join('')
}
